function renderCommandResults(){const query=($("#commandSearch")?.value||"").trim().toLowerCase(),category=$("#commandCategory")?.value||"";const items=commandCatalog.filter(command=>(!category||command.category===category)&&(!query||[command.name,command.description,command.category,command.usage,...(command.aliases||[])].join(" ").toLowerCase().includes(query)));$("#commandCount").textContent=items.length+" of "+commandCatalog.length+" commands";$("#commandList").innerHTML=items.length?items.map(command=>'<article class="command-card"><div class="command-card-head"><strong>/'+esc(command.name)+'</strong><span class="pill">'+esc(command.category)+'</span></div><p>'+esc(command.description)+'</p><code>'+esc(command.usage||("/"+command.name))+'</code>'+(command.aliases?.length?'<small>Aliases: '+command.aliases.map(esc).join(", ")+'</small>':"")+'</article>').join(""):'<div class="empty">No commands match this search.</div>'}
async function loadCommands(){try{const d=await request("/api/guild/"+guildId+"/commands");commandCatalog=d.commands||[];const categories=[...new Set(commandCatalog.map(command=>command.category||"General"))].sort();$("#commandCategory").innerHTML='<option value="">All categories</option>'+categories.map(category=>'<option value="'+esc(category)+'">'+esc(category)+'</option>').join("");$("#commandSearch").addEventListener("input",renderCommandResults);$("#commandCategory").addEventListener("change",renderCommandResults);renderCommandResults()}catch(e){$("#commandList").innerHTML=status(e.message,"bad")}}
