$("#saveLevelRewards")?.addEventListener("click",async()=>{const roleRewards=[...document.querySelectorAll('[data-reward-row]')].map(row=>({level:Number(row.querySelector('[data-reward-level]').value),roleId:row.querySelector('[data-reward-role]').value}));try{const d=await request("/api/guild/"+guildId+"/leveling/settings",{method:"POST",body:JSON.stringify({roleRewards})});settings.leveling=d.settings||settings.leveling;$("#levelRewardFeedback").innerHTML=status(d.message||"Level role rewards saved.","good")}catch(e){$("#levelRewardFeedback").innerHTML=status(e.message,"bad")}});
